%%Emilijus Gureckas; Laboratorinis darbas 5
%24 var
%%
help cell %[output:0f38da5d]
help cellfun %[output:2652748c]
help isreal %[output:6125ad2a]
help length %[output:578c4619]
help cellplot %[output:117821a1]
help cell2mat %[output:3d6c8ecb]
help isempty %[output:978fd254]
help isclass %[output:3ba5d9cb]
%%
close all
clc

C1={25, 'Labas'; true, single(2.5)};
C2={int32(10), "Tekstas"; uint8(3), {1,2}};

C=cat(3,C1,C2);

disp(C) %[output:46787e35]

figure %[output:2779d4f4]

subplot(1,2,1) %[output:2779d4f4]
cellplot(C(:,:,1)) %[output:2779d4f4]
title('1 celiu masyvo sluoksnis') %[output:2779d4f4]


subplot(1,2,2) %[output:2779d4f4]
cellplot(C(:,:,2)) %[output:2779d4f4]
title('2 celiu masyvo sluoksnis') %[output:2779d4f4]
%%
clearvars
clc

while true
    m = input('Iveskite m: ');
    n = input('Iveskite n: ');

    if m == n
        break
    end

    while m ~= n
        if m > n
            m = m - n;
        else
            n = n - m;
        end
    end

    disp('Maziausia teigiama reiksme:')
    disp(m)
end

